import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"特德·韦斯勒 (Ted Weschler)","description":"","frontmatter":{},"headers":[],"relativePath":"04_people/特德·韦斯勒.md","filePath":"04_people/特德·韦斯勒.md"}'),d={name:"04_people/特德·韦斯勒.md"};function i(o,t,h,n,s,u){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="特德·韦斯勒-ted-weschler" tabindex="-1">特德·韦斯勒 (Ted Weschler) <a class="header-anchor" href="#特德·韦斯勒-ted-weschler" aria-label="Permalink to &quot;特德·韦斯勒 (Ted Weschler)&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>全名</td><td>Theodore E. Weschler</td></tr><tr><td>出生</td><td>1960年代</td></tr><tr><td>公司</td><td><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a></td></tr><tr><td>职位</td><td>投资经理</td></tr><tr><td>任期</td><td>2012年至今</td></tr></tbody></table><h2 id="职业生涯" tabindex="-1">职业生涯 <a class="header-anchor" href="#职业生涯" aria-label="Permalink to &quot;职业生涯&quot;">​</a></h2><h3 id="早年" tabindex="-1">早年 <a class="header-anchor" href="#早年" aria-label="Permalink to &quot;早年&quot;">​</a></h3><ul><li>特德·韦斯勒（Theodore E. Weschler）早年从事资产管理行业</li><li>凭借深厚的投资研究能力，在业内积累了良好声誉</li></ul><h3 id="创办对冲基金" tabindex="-1">创办对冲基金 <a class="header-anchor" href="#创办对冲基金" aria-label="Permalink to &quot;创办对冲基金&quot;">​</a></h3><ul><li>创办并运营对冲基金 <strong>Capital Management</strong> 约 <strong>25年</strong></li><li>在创立自己的基金之前，曾在资产管理领域担任分析师</li><li>凭借出色的基本面研究能力和长期投资理念，为基金持有人创造了可观的回报</li><li>约25年的基金管理经验，使他成为华尔街最受尊敬的选股人之一</li></ul><h2 id="与巴菲特的渊源" tabindex="-1">与巴菲特的渊源 <a class="header-anchor" href="#与巴菲特的渊源" aria-label="Permalink to &quot;与巴菲特的渊源&quot;">​</a></h2><h3 id="两次天价慈善午餐" tabindex="-1">两次天价慈善午餐 <a class="header-anchor" href="#两次天价慈善午餐" aria-label="Permalink to &quot;两次天价慈善午餐&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>竞拍金额</th><th>备注</th></tr></thead><tbody><tr><td>2010年</td><td>262万美元</td><td>打破当时历史记录</td></tr><tr><td>2011年</td><td>268万美元</td><td>再次刷新记录</td></tr><tr><td><strong>合计</strong></td><td><strong>530万美元</strong></td><td>连续两年竞得</td></tr></tbody></table><ul><li>2010年，韦斯勒以 <strong>262万美元</strong> 的出价赢得巴菲特慈善午餐竞拍，这一金额打破了当时的历史纪录</li><li>2011年，他再次以 <strong>268万美元</strong> 竞得午餐，再次刷新自己创下的记录</li><li>两次午餐总共花费约 <strong>530万美元</strong>，全部捐赠给格莱德基金会（Glade Foundation）</li></ul><h3 id="午餐的意义" tabindex="-1">午餐的意义 <a class="header-anchor" href="#午餐的意义" aria-label="Permalink to &quot;午餐的意义&quot;">​</a></h3><ul><li>与巴菲特的深入交流让韦斯勒进一步了解了伯克希尔的投资哲学和文化</li><li>午餐中的讨论可能成为他最终加入伯克希尔的契机</li><li>巴菲特也借此进一步考察这位潜在的接班人选</li></ul><h2 id="加入伯克希尔" tabindex="-1">加入伯克希尔 <a class="header-anchor" href="#加入伯克希尔" aria-label="Permalink to &quot;加入伯克希尔&quot;">​</a></h2><h3 id="正式入职" tabindex="-1">正式入职 <a class="header-anchor" href="#正式入职" aria-label="Permalink to &quot;正式入职&quot;">​</a></h3><ul><li><strong>2012年1月</strong>：正式加入 <a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a></li><li>加入时，巴菲特宣布韦斯勒与另一位投资经理 <strong><a href="/04_people/托德·康姆斯.html">托德·康姆斯</a></strong>（Todd Combs）将共同管理伯克希尔的投资组合</li><li>两人被认为是巴菲特精心挑选的潜在接班团队成员</li></ul><h3 id="投资管理规模" tabindex="-1">投资管理规模 <a class="header-anchor" href="#投资管理规模" aria-label="Permalink to &quot;投资管理规模&quot;">​</a></h3><ul><li>加入后负责管理约 <strong>30亿美元</strong> 的投资组合</li><li>与 <a href="/04_people/托德·康姆斯.html">托德·康姆斯</a> 共同承担起伯克希尔投资组合的管理重任</li></ul><h2 id="投资风格" tabindex="-1">投资风格 <a class="header-anchor" href="#投资风格" aria-label="Permalink to &quot;投资风格&quot;">​</a></h2><h3 id="核心理念" tabindex="-1">核心理念 <a class="header-anchor" href="#核心理念" aria-label="Permalink to &quot;核心理念&quot;">​</a></h3><ol><li><strong>深入基本面研究</strong>：对每一家投资标的进行彻底的财务分析、商业模式评估和竞争环境研究</li><li><strong>长期持有</strong>：倾向于长期持有优质企业，不追逐短期市场波动</li><li><strong>价值导向</strong>：寻找被市场低估的优质公司，以合理价格买入优秀企业</li><li><strong>集中投资</strong>：与巴菲特类似，偏好集中持仓于最有信心的投资机会</li></ol><h3 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h3><ul><li>韦斯勒的投资理念与巴菲特高度契合</li><li>在加入伯克希尔之前，其25年的投资记录证明了他的选股能力</li><li>巴菲特对他的信任，体现在直接将数十亿美元的投资组合交由他管理</li></ul><h2 id="与托德·康姆斯的比较" tabindex="-1">与托德·康姆斯的比较 <a class="header-anchor" href="#与托德·康姆斯的比较" aria-label="Permalink to &quot;与托德·康姆斯的比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>特德·韦斯勒</th><th>托德·康姆斯</th></tr></thead><tbody><tr><td>加入时间</td><td>2012年1月</td><td>2010年</td></tr><tr><td>管理规模</td><td>约30亿美元</td><td>约30亿美元</td></tr><tr><td>背景</td><td>对冲基金经理，约25年经验</td><td>前对冲基金经理</td></tr><tr><td>投资风格</td><td>深度价值，长期持有</td><td>价值投资，关注保险等板块</td></tr></tbody></table><h2 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h2><blockquote><p>&quot;我们非常幸运能够吸引像韦斯勒和康姆斯这样才华横溢的投资经理加入伯克希尔。&quot; —— 巴菲特</p></blockquote><h3 id="接班人角色" tabindex="-1">接班人角色 <a class="header-anchor" href="#接班人角色" aria-label="Permalink to &quot;接班人角色&quot;">​</a></h3><ul><li>韦斯勒与康姆斯一同被视为巴菲特的潜在接班人</li><li>两人共同管理的投资组合已逐步扩大</li><li>他们的存在为伯克希尔的长期投资能力提供了保障</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 服务的公司</li><li><a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a> - 老板与导师</li><li><a href="/04_people/托德·康姆斯.html">托德·康姆斯</a> - 同为伯克希尔投资经理</li></ul><hr><p><em>最后更新：2026-04-12</em></p>',36)])])}const m=a(d,[["render",i]]);export{b as __pageData,m as default};
